head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 업로드 파일의 Column 수
scwin.COL_COUNT = 6;



// 이전 케이스에서 열린 Excel 파일 선택 레이어를 닫는다.
//  · 닫은 경우 true 를 반환한다. (닫기 처리가 끝나기 전에 다시 열면 ID 중복 경고가 발생하므로 호출부에서 간격을 둔다.)
scwin.closeOpened = function () {
    try {
        var objFrame = document.querySelector("[id$='_excelPop_wframe']");
        if (objFrame === null) return false;

        WebSquare.util.closePopup(objFrame.id.replace("_wframe", ""));
        return true;
    } catch (e) {}

    return false;
};



// endColumnIndex 값만 달리하여 advancedExcelUpload 실행
//  · nEnd 가 undefined 이면 endColumnIndex 를 아예 전달하지 않는다.
scwin.runCase = function (strNo, nEnd) {
    var bClosed = scwin.closeOpened();

    var fnRun = function () {
        var objOptions = { "wframe" : true };
        if (nEnd !== undefined) objOptions.endColumnIndex = nEnd;

        target1.advancedExcelUpload(objOptions);

        scwin.setReturnValue("[" + strNo + "] 설정한 endColumnIndex : " + (nEnd === undefined ? "미설정" : nEnd + " (" + (typeof nEnd) + ")"));

        // 엔진에 실제로 전달된 값은 업로드가 끝나면 비워지므로 호출 직후 바로 읽는다.
        scwin.printUploadInfo();
    };

    // 이전 레이어의 닫기 처리가 끝난 뒤 다음 케이스를 실행한다.
    if (bClosed === true) {
        setTimeout(fnRun, 800);
    } else {
        fnRun();
    }
};



// 엔진에 실제로 전달된 gridEndCol 값의 형태(타입)와 값 출력
scwin.printUploadInfo = function () {
    var strInfo = target1._excelUploadInfo;
    if (strInfo === undefined || strInfo === null || strInfo === "") {
        scwin.setReturnValue("전달된 gridEndCol : 확인 불가");
        return;
    }

    var objEndCol = JSON.parse(strInfo).gridEndCol;
    scwin.setReturnValue("전달된 gridEndCol : " + (typeof objEndCol) + " " + JSON.stringify(objEndCol));
};



// 업로드 완료 후 GridView 에 반영된 Row / Column 값 출력
scwin.target1_onfilereadend = function (value) {
    var arrData = dlt_upload.getAllJSON();

    for (var i = 0; i < arrData.length; i++) {
        var arrCol = [];
        for (var j = 0; j < scwin.COL_COUNT; j++) {
            var strVal = arrData[i]["col" + j];
            arrCol.push(strVal === undefined || strVal === null || strVal === "" ? "-" : strVal);
        }
        scwin.setReturnValue("Row " + i + " : " + arrCol.join(" | "));
    }

    scwin.setReturnValue("");
};



// ① endColumnIndex 미설정
scwin.btn_case1_onclick = function () {
    scwin.runCase("①", undefined);
};

// ② endColumnIndex 3
scwin.btn_case2_onclick = function () {
    scwin.runCase("②", 3);
};

// ③ endColumnIndex 0
scwin.btn_case3_onclick = function () {
    scwin.runCase("③", 0);
};

// ④ endColumnIndex -1
scwin.btn_case4_onclick = function () {
    scwin.runCase("④", -1);
};
